39	import org.springframework.samples.petclinic.mapper.OwnerMapper;
40	import org.springframework.samples.petclinic.mapper.PetMapper;
41	import org.springframework.samples.petclinic.mapper.VisitMapper;
42	import org.springframework.samples.petclinic.model.Owner;
43	import org.springframework.samples.petclinic.model.Pet;
44	import org.springframework.samples.petclinic.model.Visit;
45	import org.springframework.samples.petclinic.rest.advice.CityAtCapacityException;
46	import org.springframework.samples.petclinic.rest.advice.DailyRegistrationLimitException;
47	import org.springframework.samples.petclinic.rest.advice.DuplicateIdentityException;
48	import org.springframework.samples.petclinic.rest.advice.FutureRegistrationDateException;
49	import org.springframework.samples.petclinic.rest.advice.InvalidEmailException;
50	import org.springframework.samples.petclinic.rest.advice.InvalidPostcodeException;
51	import org.springframework.samples.petclinic.rest.advice.InvalidTelephoneException;
52	import org.springframework.samples.petclinic.rest.advice.MissingOwnerFieldsException;
53	import org.springframework.samples.petclinic.rest.api.OwnersApi;
54	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
55	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
56	import org.springframework.samples.petclinic.rest.dto.PetDto;
57	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
58	import org.springframework.samples.petclinic.rest.dto.VisitDto;
59	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
60	import org.springframework.samples.petclinic.service.ClinicService;
61	import org.springframework.security.access.prepost.PreAuthorize;
62	import org.springframework.web.bind.annotation.CrossOrigin;
63	import org.springframework.web.bind.annotation.RequestMapping;
64	import org.springframework.web.bind.annotation.RestController;
65	import org.springframework.web.util.UriComponentsBuilder;
66	
67	import jakarta.transaction.Transactional;
68	
69	/**
70	 * @author Vitaliy Fedoriv
71	 */
72	
73	@RestController
74	@CrossOrigin(exposedHeaders = "errors, content-type")
75	@RequestMapping("/api")
76	public class OwnerRestControllerV1 implements OwnersApi {
77	
78	    /**
79	     * A pragmatic syntactic check for an email address: a non-empty local part, an {@code @},
80	     * and a dotted domain. Deliberately conservative so obviously malformed values (e.g. a bare
81	     * word with no {@code @}) are rejected while ordinary addresses are accepted.
82	     */
83	    private static final Pattern EMAIL_PATTERN =
84	        Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
85	
86	    /** Dedicated audit logger; carries owner lifecycle side-effects. */
87	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
88	
89	    private final ClinicService clinicService;
90	
91	    private final OwnerMapper ownerMapper;
92	
93	    private final PetMapper petMapper;
94	
95	    private final VisitMapper visitMapper;
96	
97	    public OwnerRestControllerV1(ClinicService clinicService,
98	                                 OwnerMapper ownerMapper,
99	                                 PetMapper petMapper,
100	                                 VisitMapper visitMapper) {
101	        this.clinicService = clinicService;
102	        this.ownerMapper = ownerMapper;
103	        this.petMapper = petMapper;
104	        this.visitMapper = visitMapper;
105	    }
106	
107	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
108	    @Override
109	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
110	        Collection<Owner> owners;
111	        if (lastName != null) {
112	            owners = this.clinicService.findOwnerByLastName(lastName);
113	        } else {
114	            owners = this.clinicService.findAllOwners();
115	        }
116	        if (owners.isEmpty()) {
117	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
118	        }
119	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
120	    }
121	
122	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
123	    @Override
124	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
125	        Owner owner = this.clinicService.findOwnerById(ownerId);
126	        if (owner == null) {
127	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
128	        }
129	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
130	    }
131	
132	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
133	    @Override
134	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
135	        List<String> missingFields = new ArrayList<>();
136	        if (isBlank(ownerFieldsDto.getFirstName())) {
137	            missingFields.add("firstName");
138	        }
139	        if (isBlank(ownerFieldsDto.getLastName())) {
140	            missingFields.add("lastName");
141	        }
142	        String normalizedAddress = normalizeAddress(ownerFieldsDto.getAddress());
143	        if (isBlank(normalizedAddress)) {
144	            missingFields.add("address");
145	        }
146	        if (isBlank(ownerFieldsDto.getCity())) {
147	            missingFields.add("city");
148	        }
149	        if (isBlank(ownerFieldsDto.getTelephone())) {
150	            missingFields.add("telephone");
151	        }
152	        if (!missingFields.isEmpty()) {
153	            throw new MissingOwnerFieldsException(missingFields);
154	        }
155	        validatePostcode(ownerFieldsDto.getCity(), ownerFieldsDto.getPostcode());
156	        LocalDate suppliedRegistrationDate = ownerFieldsDto.getRegistrationDate();
157	        if (suppliedRegistrationDate != null && suppliedRegistrationDate.isAfter(LocalDate.now())) {
158	            throw new FutureRegistrationDateException(
159	                "registrationDate must not be later than the server date");
160	        }
161	        LocalDate registrationDate = toBusinessDay(
162	            suppliedRegistrationDate != null
163	                ? suppliedRegistrationDate
164	                : LocalDate.now());
165	        long registeredOnDay = this.clinicService.findAllOwners().stream()
166	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
167	            .count();
168	        if (registeredOnDay >= 100) {
169	            throw new DailyRegistrationLimitException(
170	                "100 or more owners have already been registered today");
171	        }
172	        boolean bulkSignupWarning = registeredOnDay > 80;
173	        String city = ownerFieldsDto.getCity();
174	        long ownersInCity = this.clinicService.findAllOwners().stream()
175	            .filter(existing -> city != null && city.equalsIgnoreCase(existing.getCity()))
176	            .count();
177	        if (ownersInCity >= 50) {
178	            throw new CityAtCapacityException(
179	                "the owner's city already contains 50 or more owners");
180	        }
181	        ownerFieldsDto.setAddress(normalizedAddress);
182	        String lastName = normalizeHousehold(ownerFieldsDto.getLastName());
183	        List<Owner> householdMembers = this.clinicService.findAllOwners().stream()
184	            .filter(existing -> lastName.equals(normalizeHousehold(existing.getLastName()))
185	                && normalizedAddress.equals(normalizeAddress(existing.getAddress())))
186	            .toList();
187	        String householdId = null;
188	        if (!householdMembers.isEmpty()) {
189	            // Owners sharing a normalized last name and address form a household with a
190	            // stable shared identifier; backfill any members created before it was formed.
191	            // The household id is part of the identity key, so two members with different
192	            // telephones have different identity keys and are both allowed.
193	            householdId = householdId(lastName, normalizedAddress);
194	            for (Owner member : householdMembers) {
195	                if (!householdId.equals(member.getHouseholdId())) {
196	                    member.setHouseholdId(householdId);
197	                    this.clinicService.saveOwner(member);
198	                }
199	            }
200	        }
201	        String telephone = toE164(ownerFieldsDto.getTelephone());
202	        ownerFieldsDto.setTelephone(telephone);
203	        String email = normalizeEmail(ownerFieldsDto.getEmail());
204	        ownerFieldsDto.setEmail(email);
205	        // Single, consolidated duplicate check: reject only when the new owner's whole
206	        // derived identity key (telephone|email|householdId) equals an existing owner's.
207	        String identityKey = IdentityKeyDeriver.identityKey(telephone, email, householdId);
208	        boolean identityInUse = this.clinicService.findAllOwners().stream()
209	            .anyMatch(existing -> identityKey.equals(IdentityKeyDeriver.identityKey(
210	                existing.getTelephone(), existing.getEmail(), existing.getHouseholdId())));
211	        if (identityInUse) {
212	            throw new DuplicateIdentityException(
213	                "an owner with the same identity key already exists");
214	        }
215	        HttpHeaders headers = new HttpHeaders();
216	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
217	        owner.setRegistrationDate(registrationDate);
218	        owner.setCustomerCode(
219	            customerCode(owner.getPostcode(), owner.getTelephone(), owner.getLastName()));
220	        owner.setHouseholdId(householdId);
221	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
222	        owner.setBulkSignupWarning(bulkSignupWarning);
223	        // Household size after this create: existing members plus the owner being created.
224	        owner.setHouseholdSize(householdMembers.size() + 1);
225	        this.clinicService.saveOwner(owner);
226	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
227	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
228	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
229	            ownerDto.getMembershipLevel());
230	        headers.setLocation(UriComponentsBuilder.newInstance()
231	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
232	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
233	    }
234	
235	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
236	    @Override
237	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
238	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
239	        if (currentOwner == null) {
240	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
241	        }
242	        currentOwner.setAddress(ownerFieldsDto.getAddress());
243	        currentOwner.setCity(ownerFieldsDto.getCity());
244	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
245	        currentOwner.setLastName(ownerFieldsDto.getLastName());
246	        currentOwner.setTelephone(toE164(ownerFieldsDto.getTelephone()));
247	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
248	        this.clinicService.saveOwner(currentOwner);
249	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
250	    }
251	
252	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
253	    @Transactional
254	    @Override
255	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
256	        Owner owner = this.clinicService.findOwnerById(ownerId);
257	        if (owner == null) {
258	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
259	        }
260	        this.clinicService.deleteOwner(owner);
261	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
262	    }
263	
264	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
265	    @Override
266	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
267	        Owner owner = this.clinicService.findOwnerById(ownerId);
268	        if (owner == null) {
269	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
270	        }
271	        HttpHeaders headers = new HttpHeaders();
272	        Pet pet = petMapper.toPet(petFieldsDto);
273	        owner.setId(ownerId);
274	        pet.setOwner(owner);
275	        pet.getType().setName(null);
276	        this.clinicService.savePet(pet);
277	        PetDto petDto = petMapper.toPetDto(pet);
278	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
279	            .buildAndExpand(pet.getId()).toUri());
280	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
281	    }
282	
283	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
284	    @Override
285	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
286	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
287	        if (currentOwner != null) {
288	            Pet currentPet = this.clinicService.findPetById(petId);
289	            if (currentPet != null) {
290	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
291	                currentPet.setName(petFieldsDto.getName());
292	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
293	                this.clinicService.savePet(currentPet);
294	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
295	            }
296	        }
297	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
298	    }
299	
300	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
301	    @Override
302	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
303	        HttpHeaders headers = new HttpHeaders();
304	        Visit visit = visitMapper.toVisit(visitFieldsDto);
305	        Pet pet = new Pet();
306	        pet.setId(petId);
307	        visit.setPet(pet);
308	        this.clinicService.saveVisit(visit);
309	        VisitDto visitDto = visitMapper.toVisitDto(visit);
310	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
311	            .buildAndExpand(visit.getId()).toUri());
312	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
313	    }
