315	
316	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
317	    @Override
318	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
319	        Owner owner = this.clinicService.findOwnerById(ownerId);
320	        if (owner != null) {
321	            Pet pet = owner.getPet(petId);
322	            if (pet != null) {
323	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
324	            }
325	        }
326	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
327	    }
328	
329	    private static boolean isBlank(String value) {
330	        return value == null || value.isBlank();
331	    }
332	
333	    /**
334	     * Rolls a registration date forward to the next business day: when it falls on a Saturday or
335	     * Sunday it is advanced to the following Monday; a weekday is returned unchanged. This is applied
336	     * to the effective registration date (whether supplied in the request or defaulted to the server
337	     * date), so every value derived from the registration date sees the adjusted business day.
338	     */
339	    private static LocalDate toBusinessDay(LocalDate date) {
340	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
341	            date = date.plusDays(1);
342	        }
343	        return date;
344	    }
345	
346	    /**
347	     * Normalizes a last name for household-duplicate comparison: leading and trailing whitespace is
348	     * trimmed, every internal run of whitespace is collapsed to a single space, and the result is
349	     * lower-cased so that last names are compared case-insensitively.
350	     */
351	    private static String normalizeHousehold(String value) {
352	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
353	    }
354	
355	    /** Common street-type abbreviations expanded to their canonical full form during normalization. */
356	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
357	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
358	
359	    /**
360	     * Normalizes an address to its canonical stored form: leading and trailing whitespace is
361	     * trimmed, every internal run of whitespace is collapsed to a single space, the result is
362	     * upper-cased, and common street-type abbreviations are expanded token-by-token
363	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} or
364	     * whitespace-only value normalizes to the empty string. This form is both stored/returned and
365	     * used for every address comparison (household-duplicate detection and the shared household id).
366	     */
367	    private static String normalizeAddress(String value) {
368	        if (value == null) {
369	            return "";
370	        }
371	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
372	        if (collapsed.isEmpty()) {
373	            return "";
374	        }
375	        String[] tokens = collapsed.split(" ");
376	        StringBuilder sb = new StringBuilder();
377	        for (int i = 0; i < tokens.length; i++) {
378	            if (i > 0) {
379	                sb.append(' ');
380	            }
381	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
382	        }
383	        return sb.toString();
384	    }
385	
386	    /**
387	     * Derives the stable {@code householdId} shared by all owners in a household. It is a
388	     * deterministic function of the normalized last name and address, so every owner that
389	     * shares those values maps to the same identifier regardless of creation order.
390	     */
391	    private static String householdId(String normalizedLastName, String normalizedAddress) {
392	        String key = normalizedLastName + "\n" + normalizedAddress;
393	        return UUID.nameUUIDFromBytes(key.getBytes(StandardCharsets.UTF_8)).toString();
394	    }
395	
396	    /**
397	     * Builds the {@code customerCode} assigned to a new owner, formatted
398	     * {@code '<REGION>-<HASH8>'}: {@code REGION} is the region code derived from the owner's postcode
399	     * ({@code NSW}/{@code VIC}/{@code QLD}, or {@code UNKNOWN}), and {@code HASH8} is the first 8
400	     * upper-case hex characters of SHA-256 over the owner's normalized E.164 telephone concatenated
401	     * with the last name (e.g. {@code 'NSW-1A2B3C4D'}). No sequence number is used, so the code is a
402	     * pure function of the owner's own identity fields.
403	     */
404	    private static String customerCode(String postcode, String telephone, String lastName) {
405	        String region = LocalityDeriver.region(postcode);
406	        String hash8 = sha256Hex8((telephone == null ? "" : telephone)
407	            + (lastName == null ? "" : lastName));
408	        return region + "-" + hash8;
409	    }
410	
411	    /** The first 8 upper-case hex characters (4 bytes) of the SHA-256 digest of {@code s}. */
412	    private static String sha256Hex8(String s) {
413	        try {
414	            byte[] digest = MessageDigest.getInstance("SHA-256")
415	                .digest(s.getBytes(StandardCharsets.UTF_8));
416	            StringBuilder sb = new StringBuilder(8);
417	            for (int i = 0; i < 4; i++) {
418	                sb.append(String.format("%02X", digest[i]));
419	            }
420	            return sb.toString();
421	        }
422	        catch (NoSuchAlgorithmException e) {
423	            throw new IllegalStateException("SHA-256 not available", e);
424	        }
425	    }
426	
427	    /**
428	     * Counts the existing owners that share the given first name and last name, compared
429	     * case-insensitively. This is evaluated over the owners that already exist (i.e. before the
430	     * owner currently being created is saved), so it reflects how many namesakes preceded the
431	     * new owner.
432	     */
433	    private int countNamesakes(String firstName, String lastName) {
434	        return (int) this.clinicService.findAllOwners().stream()
435	            .filter(existing -> firstName != null && firstName.equalsIgnoreCase(existing.getFirstName())
436	                && lastName != null && lastName.equalsIgnoreCase(existing.getLastName()))
437	            .count();
438	    }
439	
440	    /**
441	     * Normalizes a telephone number to E.164 form. Spaces, dashes and brackets are stripped. A
442	     * leading {@code '+'} and its country code are kept as-is; otherwise the number is treated as a
443	     * national one, a single leading {@code '0'} is dropped, and the default country code
444	     * {@code '+61'} is prepended. The result must have 8 to 15 digits after the {@code '+'}, and its
445	     * national number must have the length required by its country code ({@code '+61'} requires 9
446	     * national digits, {@code '+1'} requires 10); otherwise an {@link InvalidTelephoneException} is
447	     * raised (reported to the client as 400).
448	     */
449	    private static String toE164(String telephone) {
450	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s()-]", "");
451	        String digits;
452	        if (cleaned.startsWith("+")) {
453	            digits = cleaned.substring(1);
454	        } else {
455	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
456	            digits = "61" + national;
457	        }
458	        if (!digits.matches("[0-9]{8,15}")) {
459	            throw new InvalidTelephoneException(
460	                "telephone must form a valid E.164 number with 8 to 15 digits");
461	        }
462	        validateNationalLength(digits);
463	        return "+" + digits;
464	    }
465	
466	    /** National-number length required for each supported country code (digits after the code). */
467	    private static final Map<String, Integer> NATIONAL_LENGTH_BY_COUNTRY_CODE = Map.of(
468	        "61", 9, "1", 10);
469	
470	    /**
471	     * Validates the national-number length of an E.164 number (digits after the {@code '+'}) against
472	     * its country code. {@code '+61'} requires 9 national digits and {@code '+1'} requires 10; a
473	     * mismatch raises an {@link InvalidTelephoneException} (reported to the client as 400). Country
474	     * codes without a configured requirement are left to the general 8-to-15-digit rule.
475	     */
476	    private static void validateNationalLength(String digits) {
477	        for (Map.Entry<String, Integer> entry : NATIONAL_LENGTH_BY_COUNTRY_CODE.entrySet()) {
478	            String code = entry.getKey();
479	            if (digits.startsWith(code)) {
480	                int nationalLength = digits.length() - code.length();
481	                if (nationalLength != entry.getValue()) {
482	                    throw new InvalidTelephoneException(
483	                        "telephone national number must have " + entry.getValue()
484	                            + " digits for country code +" + code);
485	                }
486	                return;
487	            }
488	        }
489	    }
490	
491	    /**
492	     * Inclusive 4-digit postcode range fixed for each region: NSW 2000-2099, VIC 3000-3099,
493	     * QLD 4000-4099. A region absent from this table (i.e. a city with no known region) accepts
494	     * any 4-digit postcode.
495	     */
496	    private static final Map<String, int[]> REGION_POSTCODE_RANGE = Map.of(
497	        "NSW", new int[] {2000, 2099},
498	        "VIC", new int[] {3000, 3099},
499	        "QLD", new int[] {4000, 4099});
500	
501	    /**
502	     * Validates an owner's optional {@code postcode}. When absent (or blank) it is left unvalidated
503	     * and the owner is accepted, keeping the request contract backward-compatible. When present it
504	     * must be a 4-digit value; and when the owner's city maps to a known region it must fall within
505	     * that region's fixed inclusive range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with
506	     * no known region accepts any 4-digit postcode. A violation raises an
507	     * {@link InvalidPostcodeException} (reported to the client as 400).
508	     */
509	    private static void validatePostcode(String city, String postcode) {
510	        if (isBlank(postcode)) {
511	            return;
512	        }
513	        if (!postcode.matches("[0-9]{4}")) {
514	            throw new InvalidPostcodeException("postcode must be a 4-digit value");
515	        }
516	        int[] range = REGION_POSTCODE_RANGE.get(LocalityDeriver.localityForCity(city));
517	        if (range == null) {
518	            return;
519	        }
520	        int value = Integer.parseInt(postcode);
521	        if (value < range[0] || value > range[1]) {
522	            throw new InvalidPostcodeException(
523	                "postcode is out of range for the owner's city region");
524	        }
525	    }
526	
527	    /**
528	     * Email is optional: an absent (or blank) value is left as {@code null}. When a value is
529	     * present it must be a syntactically valid address, otherwise an {@link InvalidEmailException}
530	     * is raised (reported to the client as 400). A valid value is returned lower-cased so it is
531	     * stored and returned in canonical form.
532	     */
533	    private static String normalizeEmail(String email) {
534	        if (isBlank(email)) {
535	            return null;
536	        }
537	        String trimmed = email.trim();
538	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
539	            throw new InvalidEmailException("email must be a syntactically valid address");
540	        }
541	        return trimmed.toLowerCase(Locale.ROOT);
542	    }
543	}
